package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for calculateNumericalVariance method in HypergeometricDistribution.
 * Since the method is protected, we access it via a subclass or by being in the same package.
 */
public class HypergeometricDistribution_calculateNumericalVariance_TriageGen0Test {

    /**
     * A test wrapper to expose the protected method for testing purposes.
     */
    private static class TestableHypergeometricDistribution extends HypergeometricDistribution {
        public TestableHypergeometricDistribution(int populationSize, int numberOfSuccesses, int sampleSize) {
            super(populationSize, numberOfSuccesses, sampleSize);
        }

        @Override
        public double calculateNumericalVariance() {
            return super.calculateNumericalVariance();
        }
    }

    private static final double DELTA = 1e-12;

    @Test
    public void testCalculateNumericalVariance_StandardCase() {
        // N=100, m=20, n=10
        // Variance = (10 * 20 * (100 - 10) * (100 - 20)) / (100 * 100 * (100 - 1))
        // Variance = (200 * 90 * 80) / (10000 * 99)
        // Variance = 1440000 / 990000 = 1.454545454545...
        int N = 100;
        int m = 20;
        int n = 10;
        double expected = (double) (n * m * (N - n) * (N - m)) / (N * N * (N - 1));

        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);
        Assert.assertEquals(expected, dist.calculateNumericalVariance(), DELTA);
    }

    @Test
    public void testCalculateNumericalVariance_SmallestValidPopulation() {
        // N=2, m=1, n=1
        // Variance = (1 * 1 * (2 - 1) * (2 - 1)) / (2 * 2 * (2 - 1))
        // Variance = (1 * 1 * 1 * 1) / (4 * 1) = 0.25
        int N = 2;
        int m = 1;
        int n = 1;
        double expected = 0.25;

        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);
        Assert.assertEquals(expected, dist.calculateNumericalVariance(), DELTA);
    }

    @Test
    public void testCalculateNumericalVariance_ZeroSuccesses() {
        // m=0 should result in variance 0
        int N = 100;
        int m = 0;
        int n = 10;

        // Note: The constructor might throw NotPositiveException if m <= 0 depending on implementation constraints,
        // but mathematically for the formula:
        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, 1, n);
        // We use a setup where m is 0 if allowed, but since m must be positive per common Hypergeometric rules,
        // we check the formula behavior specifically.
        // If the constructor requires m > 0, we test the boundary.

        // Assuming m must be > 0 per constructor constraints:
        // We test with m=1, n=1, N=100
        // (1 * 1 * 99 * 99) / (100 * 100 * 99) = 99 / 10000 = 0.0099
        TestableHypergeometricDistribution dist2 = new TestableHypergeometricDistribution(100, 1, 1);
        Assert.assertEquals(0.0099, dist2.calculateNumericalVariance(), DELTA);
    }

    @Test
    public void testCalculateNumericalVariance_SampleEqualsPopulation() {
        // n = N -> (N-n) = 0 -> Variance = 0
        int N = 50;
        int m = 10;
        int n = 50;

        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);
        Assert.assertEquals(0.0, dist.calculateNumericalVariance(), DELTA);
    }

    @Test
    public void testCalculateNumericalVariance_SuccessesEqualsPopulation() {
        // m = N -> (N-m) = 0 -> Variance = 0
        int N = 50;
        int m = 50;
        int n = 10;

        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);
        Assert.assertEquals(0.0, dist.calculateNumericalVariance(), DELTA);
    }

    @Test(expected = NotPositiveException.class)
    public void testConstructor_InvalidPopulation() {
        new TestableHypergeometricDistribution(0, 1, 1);
    }

    @Test(expected = NotPositiveException.class)
    public void testConstructor_InvalidSuccesses() {
        new TestableHypergeometricDistribution(10, 0, 1);
    }

    @Test(expected = NotPositiveException.class)
    public void testConstructor_InvalidSampleSize() {
        new TestableHypergeometricDistribution(10, 5, 0);
    }
}
